namespace mediav1 = ::aedst::media::v1;
namespace adminv1 = ::aedst::admin::v1;
using network::AuthRequirement;
using network::Idempotency;
using network::makeMethod;
using network::Method;

// --- aedst.auth.v1.AuthService --------------------------------------------------

inline constexpr auto kAuthRegister = makeMethod<authv1::RegisterRequest, authv1::RegisterResponse>(
    "/aedst.auth.v1.AuthService/Register", AuthRequirement::Public);
inline constexpr auto kAuthLogin = makeMethod<authv1::LoginRequest, authv1::LoginResponse>(
    "/aedst.auth.v1.AuthService/Login", AuthRequirement::Public);
inline constexpr auto kAuthRefreshToken = makeMethod<authv1::RefreshTokenRequest, authv1::RefreshTokenResponse>(
    "/aedst.auth.v1.AuthService/RefreshToken", AuthRequirement::Public);
// Public: the refresh token in the body is the credential; a stale bearer must not block logout.
inline constexpr auto kAuthLogout = makeMethod<authv1::LogoutRequest, authv1::LogoutResponse>(
    "/aedst.auth.v1.AuthService/Logout", AuthRequirement::Public);
inline constexpr auto kAuthGetCurrentUser = makeMethod<authv1::GetCurrentUserRequest, authv1::GetCurrentUserResponse>(
    "/aedst.auth.v1.AuthService/GetCurrentUser", AuthRequirement::Required, Idempotency::Idempotent);

