inline constexpr auto kNotificationsListNotifications =
    makeMethod<notificationsv1::ListNotificationsRequest, notificationsv1::ListNotificationsResponse>(
        "/aedst.notifications.v1.NotificationsService/ListNotifications", AuthRequirement::Required,
        Idempotency::Idempotent);
